import { z } from "zod";
import { type Harness, harnessIds, harnessLabels } from "../evaluation/models.js";
import { harborAgentOptions } from "./harbor-agent-options.js";

/**
 * Harness options: what a run condition sets on each harness's Harbor agent, beside its skills and
 * instructions. Which options there are comes from the installed Harbor
 * (harbor-agent-options.ts, generated by scripts/harbor_agent_options.py), so a Harbor upgrade
 * brings its new knobs. Shared with the Run page, so nothing here may need Node.
 */

type HarborOptionKind = "string" | "integer" | "number" | "boolean" | "enum" | "object";

/** One option of a harness's Harbor agent, as Harbor declares it. */
export interface HarborAgentOption {
  /** Harbor's name for it, which `--agent-kwarg` takes. */
  readonly name: string;
  readonly label: string;
  readonly kind: HarborOptionKind;
  /** An enum's values. */
  readonly values?: readonly string[];
  /** What Harbor uses when it is not set. */
  readonly default?: string | number | boolean;
  readonly description: string;
}

export type HarborAgentOptions = Record<Harness, readonly HarborAgentOption[]>;

export type HarnessOptionValue = string | number | boolean | { readonly [key: string]: unknown };
/** A condition's options, by harness and then by Harbor's option name. */
export type HarnessOptions = Partial<Record<Harness, Readonly<Record<string, HarnessOptionValue>>>>;

/** The longest text option, such as an appended system prompt. */
export const MAX_OPTION_TEXT = 4_000;
/** The largest native config, as JSON. */
export const MAX_NATIVE_CONFIG = 20_000;
/** An agent CLI version: Harbor writes it into the install command, so only a version's own characters. */
const VERSION = /^[0-9A-Za-z][0-9A-Za-z.+-]{0,63}$/;

/** The options a condition may set on `harness`. */
export function harnessOptionsFor(harness: Harness): readonly HarborAgentOption[] {
  return harborAgentOptions[harness];
}

/** The harnesses that have any option to set. */
export const OPTION_HARNESSES = harnessIds.filter((harness) => harnessOptionsFor(harness).length);

/**
 * Settings the trial's own route owns, refused anywhere in a native config: a model, where it is
 * served, and the key that reaches it. SelfBench sets these; a config that changes them would run
 * another model than the setting names, or reach for a host the sandbox cannot.
 */
const ROUTING_KEY = /(api_?key|auth_?token|base_?url|_url|provider|^model$|^models$|^profiles?$)/i;
const ROUTING_ENV =
  /^(ANTHROPIC_|OPENAI_|CLAUDE_CODE_USE_|CLAUDE_CODE_SUBAGENT_MODEL|AWS_|VERTEX_|CLOUD_ML_|GOOGLE_|META_|MUSE_)/;
/** Settings each agent reads as its model or its key, besides the ones ROUTING_KEY names. */
const ROUTING_SETTINGS: Partial<Record<Harness, readonly string[]>> = {
  "claude-code": ["apiKeyHelper", "awsAuthRefresh", "awsCredentialExport", "forceLoginMethod"],
  codex: ["model_reasoning_effort", "review_model", "oss_provider"],
};

function routingKey(harness: Harness, value: unknown, path: string[] = []): string | undefined {
  if (Array.isArray(value)) {
    for (const item of value) {
      const found = routingKey(harness, item, path);
      if (found) return found;
    }
    return undefined;
  }
  if (!value || typeof value !== "object") return undefined;
  for (const [key, inner] of Object.entries(value)) {
    const at = [...path, key];
    if (path.length === 0 && ROUTING_SETTINGS[harness]?.includes(key)) return at.join(".");
    if (ROUTING_KEY.test(key)) return at.join(".");
    // An agent's `env` setting sets its process's variables (Claude Code's settings.json).
    if (key === "env" && inner && typeof inner === "object")
      for (const name of Object.keys(inner))
        if (ROUTING_ENV.test(name)) return [...at, name].join(".");
    const found = routingKey(harness, inner, at);
    if (found) return found;
  }
  return undefined;
}

/** Why `value` can't be `name` on `harness`, if it can't. */
export function harnessOptionProblem(
  harness: Harness,
  name: string,
  value: unknown,
): string | undefined {
  const label = harnessLabels[harness];
  const option = harnessOptionsFor(harness).find((entry) => entry.name === name);
  if (!option) return `${name} is not a ${label} option`;
  const named = `${label} ${option.label}`;
  switch (option.kind) {
    case "boolean":
      return typeof value === "boolean" ? undefined : `${named} is true or false`;
    case "integer":
      return typeof value === "number" && Number.isSafeInteger(value) && value >= 0
        ? undefined
        : `${named} is a whole number`;
    case "number":
      return typeof value === "number" && Number.isFinite(value)
        ? undefined
        : `${named} is a number`;
    case "enum":
      return typeof value === "string" && option.values?.includes(value)
        ? undefined
        : `${named} is one of ${option.values?.join(", ")}`;
    case "string":
      if (typeof value !== "string" || !value.trim()) return `${named} is text`;
      if (value.length > MAX_OPTION_TEXT)
        return `${named} is at most ${MAX_OPTION_TEXT} characters`;
      if (name === "version" && !VERSION.test(value)) return `${named} is a version, like 2.1.3`;
      return undefined;
    case "object": {
      if (!value || typeof value !== "object" || Array.isArray(value))
        return `${named} is a JSON object`;
      if (JSON.stringify(value).length > MAX_NATIVE_CONFIG)
        return `${named} is at most ${MAX_NATIVE_CONFIG} characters of JSON`;
      const routing = routingKey(harness, value);
      return routing
        ? `${named} can't set ${routing}: the run's model and its route are set by SelfBench`
        : undefined;
    }
  }
}

export const harnessOptionsSchema = z
  .partialRecord(z.enum(harnessIds), z.record(z.string(), z.unknown()))
  .superRefine((given, context) => {
    for (const [harness, options] of Object.entries(given) as [Harness, Record<string, unknown>][])
      for (const [name, value] of Object.entries(options)) {
        const problem = harnessOptionProblem(harness, name, value);
        if (problem) context.addIssue({ code: "custom", message: problem, path: [harness, name] });
      }
  })
  .transform((given): HarnessOptions => {
    // A harness with nothing set is no different from not naming it.
    const kept = Object.entries(given).filter(([, options]) => Object.keys(options).length);
    return Object.fromEntries(kept) as HarnessOptions;
  });

/** The `harbor run` arguments that set `harness`'s options; each value is JSON, as Harbor parses it. */
export function harnessOptionArguments(options: HarnessOptions | undefined, harness: Harness) {
  return Object.entries(options?.[harness] ?? {}).flatMap(([name, value]) => [
    "--agent-kwarg",
    `${name}=${JSON.stringify(value)}`,
  ]);
}

/** The same options with every object's keys in one order, so equal options digest alike. */
export function canonicalOptions(options: HarnessOptions): HarnessOptions {
  const sorted = (value: unknown): unknown =>
    Array.isArray(value)
      ? value.map(sorted)
      : value && typeof value === "object"
        ? Object.fromEntries(
            Object.keys(value)
              .sort()
              .map((key) => [key, sorted((value as Record<string, unknown>)[key])]),
          )
        : value;
  return sorted(options) as HarnessOptions;
}
